            inicial: "def taxa_de_acerto(lista):\n    # lista: valores True (acertou) e False (errou)\n    if len(lista) == 0:\n        return 0\n    acertos = 0\n    # conte os True aqui\n\n    return round(acertos / len(lista) * 100, 1)\n",
