            inicial: "listas = {}\nfor r in respostas:\n    aluno = r[\"aluno_id\"]\n    if aluno not in listas:\n        listas[aluno] = []\n    listas[aluno].append(r[\"acertou\"])\n\npor_aluno = {}\n# para cada aluno em listas, calcule a taxa com taxa_de_acerto\n",
