            esperados: [{ nome: "esperado_materia", sql: "SELECT m.nome, ROUND(AVG(CASE WHEN r.acertou THEN 100.0 ELSE 0 END), 1)::float FROM respostas r JOIN questoes q ON q.id = r.questao_id JOIN materias m ON m.id = q.materia_id WHERE r.resposta IS NOT NULL GROUP BY m.nome", forma: "linhas" }],
            preparo: "import pandas as pd\ndf = pd.DataFrame(linhas)",
