            pista: "a primeira linha junta as duas regras: <code>questao_id INTEGER PRIMARY KEY REFERENCES questoes(id)</code>. A data é <code>DATE</code>; os números com vírgula, <code>REAL</code>.",
            solucao: "CREATE TABLE revisoes (\n  questao_id INTEGER PRIMARY KEY REFERENCES questoes(id),\n  proxima DATE NOT NULL,\n  estabilidade REAL NOT NULL,\n  dificuldade REAL NOT NULL\n);",
